def lines(*values):
    return '\n'.join(map(str, values)) + '\n'


def numbers(values):
    return ' '.join(map(str, values))


def task(topic, section, slug, title, goal, statement, input_format, output_format, starter, reference, examples, oracle, encode=None, extra=()):
    """Examples precede deterministic extra cases; the oracle is not the solution."""
    if encode is None:
        encode = lambda x: lines(*x) if isinstance(x, tuple) else lines(x)
    cases = []
    seen = set()
    for item in list(examples) + list(extra):
        stdin = encode(item)
        if stdin in seen:
            continue
        seen.add(stdin)
        expected = oracle(item)
        cases.append({'input': stdin, 'output': str(expected)})
    assert len(cases) >= (1 if topic == 101 and slug == 'receipt' else 4), title
    public_cases = cases[:min(10, len(cases))]
    ident = f'py-expand-20261015-{topic}-{slug}'
    section_title = SECTIONS[topic][section]
    question = '\n\n'.join([
        statement,
        'Формат входных данных:\n' + input_format,
        'Формат выходных данных:\n' + output_format,
        'Тренируем: ' + goal + '.',
        'Пример:\nВвод:\n' + cases[0]['input'].rstrip('\n') + '\nВывод:\n' + cases[0]['output'],
    ])
    QUESTIONS.append({
        'topic': str(topic), 'sectionTitle': section_title,
        'question': {'id': ident, 'title': title, 'question': question,
                     'starterCode': starter + '\n\n# Напишите решение\n', 'tests': public_cases},
    })
    AUDIT.append({'id': ident, 'topic': topic, 'title': title, 'section': section_title,
                  'learningGoal': goal, 'prerequisites': TOPICS[topic][1],
                  'reference': reference + '\n', 'cases': cases})


