def main():
    QUESTIONS.sort(key=lambda q:(int(q['topic']),SECTIONS[int(q['topic'])].index(q['sectionTitle'])))
    AUDIT.sort(key=lambda q:(q['topic'],SECTIONS[q['topic']].index(q['section'])))
    assert len(QUESTIONS) == 152, len(QUESTIONS)
    assert len({q['question']['id'] for q in QUESTIONS}) == len(QUESTIONS)
    counts = {str(n):sum(q['topic']==str(n) for q in QUESTIONS) for n in TOPICS}
    assert counts == {str(n):40 if n==108 else 16 for n in TOPICS}, counts
    payload = {'version': '20261015', 'topics': {str(n): {'title': title, 'added': counts[str(n)]} for n,(title,_) in TOPICS.items()}, 'questions': QUESTIONS}
    target = ROOT / 'server/pythonPracticeExpansionData.json'
    target.write_text(json.dumps(payload,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    (ROOT/'output/python-practice-expansion-audit-input.json').write_text(json.dumps(AUDIT,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    report = [
        '# Новая практика Python — 15 октября 2026', '',
        '152 авторские задачи: 16 в каждой теме 101–107 и 40 в списках, включая 24 генератора списков. Кортежи и последующие темы не изменяются.', '',
        'Новые задания добавляются в конец банков. Старые идентификаторы, позиции, условия, решения учеников, теория и ссылки домашки сохраняются. Внутри подразделов новые задачи идут после старых.', '',
        'У каждой задачи есть конкретная цель в условии. Эталонные решения используют только текущую и предыдущие темы; импорт библиотек, функции, рекурсия, словари, множества, кортежи и yield не требуются.', '',
        'Проверка: scripts/audit-python-practice-expansion.py исполняет решения через точный PYTHON_RUNNER_SCRIPT платформы. Ожидаемые ответы вычисляются отдельными проверочными формулами/алгоритмами в исходнике автора. Кроме примеров есть границы, нули, отрицательные числа, повторы, отсутствие результата и детерминированные дополнительные случаи там, где они полезны.', '',
        'Автопроверка ввода/вывода проверяет результат, а не запрещает ученику более продвинутый способ решения. Форматирование пробелов проверено отдельно строго; действующий проверяющий платформы сравнивает вывод с нормализацией пробельных символов.', '',
    ]
    for topic,(title,prerequisites) in TOPICS.items():
        report += [f'## {title}', '', f'Доступные инструменты: {prerequisites}.', '', '| Задача | Подраздел | Что тренирует | Тестов на сайте / всего проверок |', '|---|---|---|---|']
        for item in AUDIT:
            if item['topic'] != topic:
                continue
            public = next(q['question']['tests'] for q in QUESTIONS if q['question']['id']==item['id'])
            report.append(f"| {item['title']} | {item['section']} | {item['learningGoal']} | {len(public)} / {len(item['cases'])} |")
        report += ['']
    (ROOT/'docs/python-practice-expansion-20261015.md').write_text('\n'.join(report).rstrip()+'\n',encoding='utf-8')
    print(json.dumps({'questions':len(QUESTIONS),'topics':counts,'publicCases':sum(len(q['question']['tests']) for q in QUESTIONS),'auditCases':sum(len(q['cases']) for q in AUDIT)},ensure_ascii=False))


